// src/pages/ResultPage.jsx
import React from "react";
import { useLocation, useNavigate } from "react-router-dom";
import "./result.css";

function ResultPage() {
  const location = useLocation();
  const navigate = useNavigate();

  // Get all data safely
  const {
    symptoms = [],
    predictions = [],
    symptom_details = [], // 👈 new field from backend
  } = location.state || {};

  return (
    <div className="result-container">
      <h2>🩺 Health Summary</h2>
      <p>Here’s what we found based on your symptoms.</p>

      {/* ─────────────── Detected Symptoms ─────────────── */}
      <div className="result-section">
        <h3>Detected Symptoms:</h3>
        <ul>
          {symptoms.length > 0 ? (
            symptoms.map((s, i) => <li key={i}>{s}</li>)
          ) : (
            <li>No symptoms detected.</li>
          )}
        </ul>
      </div>

      {/* ─────────────── Symptom Details ─────────────── */}
      {symptom_details && symptom_details.length > 0 && (
        <div className="result-section">
          <h3>Symptom Details:</h3>
          <div className="result-section-card">
            {symptom_details.map((item, i) => (
              <div key={i} className="symptom-card">
                <h4>• {item.symptom}</h4>
                <p>
                  <b>Description:</b> {item.description}
                </p>
                <p>
                  <b>Common causes:</b> {item.common_causes}
                </p>
                <p>
                  <b>Advice:</b> {item.advice}
                </p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ─────────────── Possible Conditions ─────────────── */}
      <div className="result-section">
        <h3>Possible Conditions:</h3>
        <ul>
          {predictions.length > 0 ? (
            predictions.map((p, i) => (
              <li key={i}>
                <b>{p.disease}</b> — confidence: {Math.round(p.score * 100)}%
              </li>
            ))
          ) : (
            <li>No predictions available.</li>
          )}
        </ul>
      </div>

      {/* ─────────────── Button ─────────────── */}
      <button onClick={() => navigate("/")} className="btn-back">
        Back to Chat
      </button>
    </div>
  );
}

export default ResultPage;
